// src/services/api.js

const BASE_URL = '';

async function request(path, options = {}) {
  const response = await fetch(`${BASE_URL}${path}`, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...options.headers },
    ...options,
  });
  if (!response.ok) {
    let errorText = `Request failed: ${response.status}`;
    try {
      const data = await response.json();
      errorText = data.message || errorText;
    } catch {}
    throw new Error(errorText);
  }
  return response.json();
}

export function login(body) {
  return request('/auth/login', { method: 'POST', body: JSON.stringify(body) });
}

export function register(body) {
  return request('/auth/register', { method: 'POST', body: JSON.stringify(body) });
}

export function getQuestions() {
  return request('/questions');
}

export function getQuestionById(id) {
  return request(`/questions/${id}`);
}

export function postQuestion(question) {
  return request('/questions', { method: 'POST', body: JSON.stringify(question) });
}

export function getAnswersByQuestionId(id) {
  return request(`/answers/question/${id}`);
}

export function postAnswer(questionId, answer) {
  return request(`/questions/${questionId}/answers`, { method: 'POST', body: JSON.stringify(answer) });
}
